<?php require '_header.php';$page_title='Payment settings';$settings=$pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['upi_id','bank_details','payment_qr'] as $key){$val=trim($_POST[$key]??'');$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute([$key,$val]);}flash('Payment instructions saved.');redirect('settings.php');}?><div class="admin-top"><div><span class="eyebrow">PAYMENT CONFIGURATION</span><h1>Payment settings</h1><p class="muted">Set the UPI ID, bank transfer instructions and QR image path.</p></div></div><div class="panel" style="margin-top:0"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>UPI ID</label><input name="upi_id" value="<?=e($settings['upi_id']??'')?>" required></div><div class="field"><label>Bank transfer instructions</label><textarea name="bank_details" required><?=e($settings['bank_details']??'')?></textarea></div><div class="field"><label>QR image path</label><input name="payment_qr" value="<?=e($settings['payment_qr']??'assets/images/payment-qr.png')?>" required><p class="muted">For the current page, put your image at <b>assets/images/payment-qr.png</b>. Use your own genuine merchant QR.</p></div><button class="btn btn-primary">Save payment settings →</button></form></div><?php require '_footer.php';?>
